const actor = this.actor(index);
const rect = this.itemRect(index);
const x = rect.width - 543; // <-- adjust this number as you prefer
const y = rect.y + 113; // <-- adjust this number as you prefer
this.drawActorCharacter(actor, x, y);
}
})()
