I think you can just imitate the existing draw functions to add the sideview battler sprite like below (for base rpg maker). You don't need any indexes, because you just take the first (or I made it to take the middle) pic from the idle pose. Then add in the status draw function to draw the sprite for
this._actor.battlerName()
. I had to add that load listener to it though, so it does the blt and refresh as it wasn't loaded fast enough. I tested it and it seems to work, change the coordinates in the draw function to move it around.
Window_Status.prototype.drawBlock2 = function() {
const y = this.block2Y();
this.drawActorFace(this._actor, 12, y);
this.drawBasicInfo(204, y);
this.drawExpInfo(456, y);
this.drawSideviewCharacterSprite(this._actor.battlerName(), 70, y + 230);
};
Window_Base.prototype.drawSideviewCharacterSprite = function(
fileName, x, y
) {
const bitmap = ImageManager.loadSvActor(fileName);
const pw = Math.round(bitmap.width / 9);
const ph = Math.round(bitmap.height / 6);
const sx = pw;
const sy = 0;
if (bitmap.isReady()) {
this.contents.blt(bitmap, sx, sy, pw, ph, x - pw / 2, y - ph);
} else {
bitmap.addLoadListener(() => this.refresh())
}
};

